(1405372, 181030, 24983, '<td valign="top">perfect image 10</td>', 'perfect image 10', '2005-05-23 03:40:42.000000', NULL, 1),
(1405375, 180287, 24983, '<td valign="top">well photographed verynicely lit. 10</td>', 'well photographed verynicely lit. 10', '2005-05-23 03:42:22.000000', NULL, 1),
(1405395, 180215, 9906, '<td valign="top">Interesting effect.  Not sure the subject is perfect for the technique...  Painted?<br/>TC</td>', 'Interesting effect.  Not sure the subject is perfect for the technique...  Painted?TC', '2005-05-23 03:55:52.000000', NULL, 1),
(1405411, 180737, 9906, '<td valign="top">This is one of my favorite types of shots to comment on.  You have so much going on here that is in your favor.  You have excellent leading lines drawing you into the frame.  You got great textures both in the lighting itself and in the plants that surround the light.  So much potential.<br/>But Ya got a couple of hot spots under the lights and in the lights themselves.  Not in itself a problem if they fit n with the mood of the shot.  You are also a little crooked.  In itself also not a prob...  However...<br/>The shot really doesn''t have a subject.  Something to make your eye rest upon.  Like a dot to dot with a couple numbers missing...  Put a person walking out of the frame in the distance.  Just an outline dimly lit and this shot would be perfect!  <br/>TC</td>', 'This is one of my favorite types of shots to comment on.  You have so much going on here that is in your favor.  You have excellent leading lines drawing you into the frame.  You got great textures both in the lighting itself and in the plants that surround the light.  So much potential.But Ya got a couple of hot spots under the lights and in the lights themselves.  Not in itself a problem if they fit n with the mood of the shot.  You are also a little crooked.  In itself also not a prob...  However...The shot really doesn''t have a subject.  Something to make your eye rest upon.  Like a dot to dot with a couple numbers missing...  Put a person walking out of the frame in the distance.  Just an outline dimly lit and this shot would be perfect!  TC', '2005-05-23 04:07:42.000000', NULL, 1),
(1405413, 179076, 9906, '<td valign="top">Impressive border!<br/>TC</td>', 'Impressive border!TC', '2005-05-23 04:08:58.000000', NULL, 1),
