(1405963, 180587, 9939, '<td valign="top">I really like the idea here. I think it could have been better executed technically. The lighter portions of the image are quite gray and what we can see if the eye doesn''t have enough detail to really draw me into the photo. The figure is definitely cloaked in shadow- too much so for my tastes.</td>', 'I really like the idea here. I think it could have been better executed technically. The lighter portions of the image are quite gray and what we can see if the eye doesn''t have enough detail to really draw me into the photo. The figure is definitely cloaked in shadow- too much so for my tastes.', '2005-05-23 12:13:35.000000', NULL, 1),
(1405965, 179076, 9939, '<td valign="top">This is a lovely image. I would like to see a little more light in the eye, and way less border. The soft focus effect works well for a shot like this, in my opinion.</td>', 'This is a lovely image. I would like to see a little more light in the eye, and way less border. The soft focus effect works well for a shot like this, in my opinion.', '2005-05-23 12:14:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1405968, 179853, 9939, '<td valign="top">Nice, slick, clean, Matrix like. I''m not crazy about the black vertical borders at all though.</td>', 'Nice, slick, clean, Matrix like. I''m not crazy about the black vertical borders at all though.', '2005-05-23 12:15:51.000000', NULL, 1),
(1405969, 180587, 24454, '<td valign="top">Striking use of light.   Awesome picture.</td>', 'Striking use of light.   Awesome picture.', '2005-05-23 12:16:35.000000', NULL, 1),
(1405970, 180287, 9939, '<td valign="top">In my opinion this is too small and too dark. Great idea, but needs more time spent on execution, I think. The positioning of the feet and the fact that it appears the frame cuts right through the left foot is also quite awkward.</td>', 'In my opinion this is too small and too dark. Great idea, but needs more time spent on execution, I think. The positioning of the feet and the fact that it appears the frame cuts right through the left foot is also quite awkward.', '2005-05-23 12:17:07.000000', NULL, 1),
(1405974, 180606, 22689, '<td valign="top">Your model has a beautiful skin !</td>', 'Your model has a beautiful skin !', '2005-05-23 12:19:44.000000', NULL, 1),
(1405975, 180842, 9939, '<td valign="top">Very painterly- excellent effect. I might have shot it fom a slightly different angle, lowering the camera to be a bit more level with the corn. I also might have lightened it up just a tad, but that''s strictly a matter of personal taste. Still an 8.</td>', 'Very painterly- excellent effect. I might have shot it fom a slightly different angle, lowering the camera to be a bit more level with the corn. I also might have lightened it up just a tad, but that''s strictly a matter of personal taste. Still an 8.', '2005-05-23 12:20:16.000000', NULL, 1),
(1405979, 179337, 9939, '<td valign="top">Looks like a bit of motion blur here. In combination with the noise from the relatively low light, for me it really detracts from a really nice set up and lovely model.</td>', 'Looks like a bit of motion blur here. In combination with the noise from the relatively low light, for me it really detracts from a really nice set up and lovely model.', '2005-05-23 12:23:41.000000', NULL, 1),
(1405983, 181017, 10848, '<td valign="top">Outstanding use of natural light. Wonderful capture!</td>', 'Outstanding use of natural light. Wonderful capture!', '2005-05-23 12:27:24.000000', NULL, 1),
(1405987, 179099, 10848, '<td valign="top">Wonderful lighting, soft yet very detailed. I like it!</td>', 'Wonderful lighting, soft yet very detailed. I like it!', '2005-05-23 12:31:04.000000', NULL, 1),
(1405991, 181032, 10848, '<td valign="top">Gorgeous! Wonderful use of natural lighting. Wonderful subjects, such a free spirited capture.</td>', 'Gorgeous! Wonderful use of natural lighting. Wonderful subjects, such a free spirited capture.', '2005-05-23 12:33:36.000000', NULL, 1),
