(1406792, 180998, 35122, '<td valign="top">lovely...</td>', 'lovely...', '2005-05-23 18:18:57.000000', NULL, 1),
(1406793, 181011, 6349, '<td valign="top">great shot.  i like the bits of color of the chair and outdoor trees.</td>', 'great shot.  i like the bits of color of the chair and outdoor trees.', '2005-05-23 18:19:41.000000', NULL, 1),
(1406796, 179582, 35122, '<td valign="top">gorgeous shot...</td>', 'gorgeous shot...', '2005-05-23 18:20:32.000000', NULL, 1),
(1406797, 180215, 6349, '<td valign="top">great shot on many levels.</td>', 'great shot on many levels.', '2005-05-23 18:21:01.000000', NULL, 1),
(1406810, 180034, 6349, '<td valign="top">wow.  i almost submitted a photo that looked just like this but the guard in mine wasn''t wearing as cool an outfit.  Great work.  One of the best in the challenge.</td>', 'wow.  i almost submitted a photo that looked just like this but the guard in mine wasn''t wearing as cool an outfit.  Great work.  One of the best in the challenge.', '2005-05-23 18:26:09.000000', NULL, 1),
(1406814, 180811, 6349, '<td valign="top">gorgeous lighting.  the grainyness and loss of detail in the tree is the only thing negative about this stunning photo.  Great work.  One of the best in the challenge.</td>', 'gorgeous lighting.  the grainyness and loss of detail in the tree is the only thing negative about this stunning photo.  Great work.  One of the best in the challenge.', '2005-05-23 18:27:28.000000', NULL, 1),
(1406818, 180842, 6349, '<td valign="top">This is stunning.  Can''t believe I''m going to add a photo of corn to my favorites.....10</td>', 'This is stunning.  Can''t believe I''m going to add a photo of corn to my favorites.....10', '2005-05-23 18:28:34.000000', NULL, 1),
