INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1406823, 180602, 6349, '<td valign="top">Congrats on your ribbon.  10.  Adding to favorites.</td>', 'Congrats on your ribbon.  10.  Adding to favorites.', '2005-05-23 18:32:37.000000', NULL, 1),
(1406826, 180798, 6349, '<td valign="top">congrats on the ribbon.  10.  adding to favs.</td>', 'congrats on the ribbon.  10.  adding to favs.', '2005-05-23 18:33:06.000000', NULL, 1),
(1406853, 178911, 31239, '<td valign="top">This image is too top heavy, if all the sky was removed it would have so much more impact.<br/>other wise good image</td>', 'This image is too top heavy, if all the sky was removed it would have so much more impact.other wise good image', '2005-05-23 18:46:37.000000', NULL, 1),
(1406866, 180897, 24454, '<td valign="top">Amazing use of light in a very striking photograph!    Very photojournalist looking.  It makes me wonder what it was like to be there.   I love it!!!!!! 10</td>', 'Amazing use of light in a very striking photograph!    Very photojournalist looking.  It makes me wonder what it was like to be there.   I love it!!!!!! 10', '2005-05-23 18:52:53.000000', NULL, 1),
(1406869, 180707, 5705, '<td valign="top">Thumbnail caught my eye, Fullsize is even more beustifull..<br/>Excellent light, not too harshe at any point on any of the pears.<br/>If I had one small nitpick, it would be one of the pears has lost most of its stem, but thats not enough to distract me from giving you a full blown 10!</td>', 'Thumbnail caught my eye, Fullsize is even more beustifull..Excellent light, not too harshe at any point on any of the pears.If I had one small nitpick, it would be one of the pears has lost most of its stem, but thats not enough to distract me from giving you a full blown 10!', '2005-05-23 18:53:57.000000', NULL, 1),
(1406874, 180526, 24454, '<td valign="top">Very cool photo.    Your use of light is so striking.   I would kind of like to see a little more outline of his neck and shoulders, but it''s still an awesome image anyway.</td>', 'Very cool photo.    Your use of light is so striking.   I would kind of like to see a little more outline of his neck and shoulders, but it''s still an awesome image anyway.', '2005-05-23 18:55:50.000000', NULL, 1),
(1406875, 180975, 509, '<td valign="top">Appears a little soft to me.  The lighting and composition is good, but the post processing doesn''t add to this imho.</td>', 'Appears a little soft to me.  The lighting and composition is good, but the post processing doesn''t add to this imho.', '2005-05-23 18:56:21.000000', NULL, 1),
(1406878, 180769, 24454, '<td valign="top">Yes it is!    All week, I kept eyeballing thesky hoping for sunrays like this -- but they never appeared.   But even if they had, it would have been in my local Texas surroundings, and never would have competed with the image you have here.  This is beautiful!   Great job picturing light!</td>', 'Yes it is!    All week, I kept eyeballing thesky hoping for sunrays like this -- but they never appeared.   But even if they had, it would have been in my local Texas surroundings, and never would have competed with the image you have here.  This is beautiful!   Great job picturing light!', '2005-05-23 18:57:26.000000', NULL, 1),
(1406883, 179559, 327, '<td valign="top">Love her..sweet. I would like the top a bit tighter..seems a lot of dead space there and a bit dark up there.<br/>Her skin tone is nice and the focus is a tiny bit soft for a portrait. Over all...very nice, good shot and the light in her eyes is the bonus.</td>', 'Love her..sweet. I would like the top a bit tighter..seems a lot of dead space there and a bit dark up there.Her skin tone is nice and the focus is a tiny bit soft for a portrait. Over all...very nice, good shot and the light in her eyes is the bonus.', '2005-05-23 18:59:06.000000', NULL, 1),
(1406884, 181023, 24454, '<td valign="top">I love this!    What a great double depiction of light.  Because the light on the Bible is very distinctive and striking -- but the real light is the Bible itself, right?   Great job.</td>', 'I love this!    What a great double depiction of light.  Because the light on the Bible is very distinctive and striking -- but the real light is the Bible itself, right?   Great job.', '2005-05-23 18:59:07.000000', NULL, 1),
(1406887, 179746, 327, '<td valign="top">I like this. Like the b&amp;w, like the subject and the light is very cool. Spot light! Nice one.</td>', 'I like this. Like the b&w, like the subject and the light is very cool. Spot light! Nice one.', '2005-05-23 18:59:45.000000', NULL, 1),
(1406892, 180502, 33515, '<td valign="top">The lighting and position of the mic is good and the  photograph has a great look, I don''t care much for the light in the top right.</td>', 'The lighting and position of the mic is good and the  photograph has a great look, I don''t care much for the light in the top right.', '2005-05-23 19:01:09.000000', NULL, 1),
(1406893, 179491, 509, '<td valign="top">Always a good subject for light, but the composition here could be improved imho.  My eyes are drawn to the roof of the house for its sharp edges and bright red.  It competes with the rainbow for attention.  Also, the post processing looks a little rushed.  There is a clear and noticeable line separating the trees from the sky.  To me it looks like either a little too much use of the clone tool or a composite image.  The rainbow in itself is good, but I think the rest of the image really needs work.  A softer background/foreground would better compliment the rainbow in my opinion.</td>', 'Always a good subject for light, but the composition here could be improved imho.  My eyes are drawn to the roof of the house for its sharp edges and bright red.  It competes with the rainbow for attention.  Also, the post processing looks a little rushed.  There is a clear and noticeable line separating the trees from the sky.  To me it looks like either a little too much use of the clone tool or a composite image.  The rainbow in itself is good, but I think the rest of the image really needs work.  A softer background/foreground would better compliment the rainbow in my opinion.', '2005-05-23 19:01:19.000000', NULL, 1),
(1406899, 180915, 24454, '<td valign="top">What a sweet contented face!!     I just love this picture.   What a capture.</td>', 'What a sweet contented face!!     I just love this picture.   What a capture.', '2005-05-23 19:02:28.000000', NULL, 1),
(1406900, 181005, 509, '<td valign="top">Great capture!  His pose is really accentuated by your composition of the photo.  The soft colors really emphasize the lighting as well.</td>', 'Great capture!  His pose is really accentuated by your composition of the photo.  The soft colors really emphasize the lighting as well.', '2005-05-23 19:02:38.000000', NULL, 1),
(1406905, 180258, 33515, '<td valign="top">Very striking, the lions head is lit nicely</td>', 'Very striking, the lions head is lit nicely', '2005-05-23 19:04:04.000000', NULL, 1),
(1406911, 180995, 9939, '<td valign="top">the color here is quite intense, perhaps too much so for my taste. Would work great for a horror movie still :)</td>', 'the color here is quite intense, perhaps too much so for my taste. Would work great for a horror movie still :)', '2005-05-23 19:06:41.000000', NULL, 1),
(1406912, 180748, 509, '<td valign="top">Could benefit from some noise reduction software, as well as a counter-clockwise rotation of about 2-3 degrees.  Compositionally I''d like to see more of the ships in the scene, backlit by the moon.  The town isn''t the focus of this shot, but occupies a large portion of the image.</td>', 'Could benefit from some noise reduction software, as well as a counter-clockwise rotation of about 2-3 degrees.  Compositionally I''d like to see more of the ships in the scene, backlit by the moon.  The town isn''t the focus of this shot, but occupies a large portion of the image.', '2005-05-23 19:06:46.000000', NULL, 1),
(1406915, 180998, 9939, '<td valign="top">Wow. Lovely color and movement. Can''t wait to hear more about this one at challenge''s end.</td>', 'Wow. Lovely color and movement. Can''t wait to hear more about this one at challenge''s end.', '2005-05-23 19:07:16.000000', NULL, 1),
(1406917, 180909, 34759, '<td valign="top">Very interesting shot. I like it a lot!</td>', 'Very interesting shot. I like it a lot!', '2005-05-23 19:08:20.000000', NULL, 1),
(1406919, 181010, 33515, '<td valign="top">Very nicely done, the background maybe a little over cooked but the reflection is nice</td>', 'Very nicely done, the background maybe a little over cooked but the reflection is nice', '2005-05-23 19:08:31.000000', NULL, 1),
(1406921, 180925, 509, '<td valign="top">I like the idea and the appearance of the water.  I think this would be much more powerful though in a landscape format and with the sun off center to the left.</td>', 'I like the idea and the appearance of the water.  I think this would be much more powerful though in a landscape format and with the sun off center to the left.', '2005-05-23 19:08:41.000000', NULL, 1),
(1406923, 180478, 34759, '<td valign="top">I really like this.. the colors work well together and the ray of light shining through really adds to the photo.</td>', 'I really like this.. the colors work well together and the ray of light shining through really adds to the photo.', '2005-05-23 19:09:51.000000', NULL, 1),
(1406925, 180596, 34759, '<td valign="top">Is that an angry nun or am I seeing things? How odd.</td>', 'Is that an angry nun or am I seeing things? How odd.', '2005-05-23 19:10:36.000000', NULL, 1),
