(1407764, 180656, 6702, '<td valign="top">I''m kind of tired of flowers, but this one caught my eye. Very nice.</td>', 'I''m kind of tired of flowers, but this one caught my eye. Very nice.', '2005-05-24 02:16:48.000000', NULL, 1),
(1407766, 178953, 6702, '<td valign="top">Still trying to figure out what exactly it is, but I like it.</td>', 'Still trying to figure out what exactly it is, but I like it.', '2005-05-24 02:18:00.000000', NULL, 1),
(1407768, 180823, 34217, '<td valign="top">The challenge was to use light in a creative way that makes if a key element.  While light is always key, I don''t feel like you used it in a creative way and I don''t even feel like this is lit as well as it could be.  I do think that the facial expressions and posing is very good, but I think your light source is to low and lighting up at the girls.  Had you brought your souce up more I think the shadows on the faces would be more appealing.  Please don''t take this the wrong way because the lighting is decent, but I think it could be improved.</td>', 'The challenge was to use light in a creative way that makes if a key element.  While light is always key, I don''t feel like you used it in a creative way and I don''t even feel like this is lit as well as it could be.  I do think that the facial expressions and posing is very good, but I think your light source is to low and lighting up at the girls.  Had you brought your souce up more I think the shadows on the faces would be more appealing.  Please don''t take this the wrong way because the lighting is decent, but I think it could be improved.', '2005-05-24 02:19:32.000000', NULL, 1),
(1407769, 180880, 34217, '<td valign="top">this does not feel like morning light to me, maybe overcast morning light, but it is flat and I don''t feel like you used light in a creative way</td>', 'this does not feel like morning light to me, maybe overcast morning light, but it is flat and I don''t feel like you used light in a creative way', '2005-05-24 02:20:51.000000', NULL, 1),
(1407770, 180752, 34217, '<td valign="top">kinda boring, sorry</td>', 'kinda boring, sorry', '2005-05-24 02:21:12.000000', NULL, 1),
(1407771, 179974, 6702, '<td valign="top">I''m sure this wasn''t just a casual shot of something, but I have absolutely no idea what it is.</td>', 'I''m sure this wasn''t just a casual shot of something, but I have absolutely no idea what it is.', '2005-05-24 02:21:13.000000', NULL, 1),
(1407772, 180313, 34217, '<td valign="top">the challenge was to use light in an creative way this is not very creative</td>', 'the challenge was to use light in an creative way this is not very creative', '2005-05-24 02:22:18.000000', NULL, 1),
