(1414669, 179746, 31036, '<td valign="top">This would make an outstanding portfolio piece. The single thing I''d change is the positioning of the tripod... and just slightly. I doubt I''ll find a photo in this challenge that I will like more than this. EXCELLENT JOB!</td>', 'This would make an outstanding portfolio piece. The single thing I''d change is the positioning of the tripod... and just slightly. I doubt I''ll find a photo in this challenge that I will like more than this. EXCELLENT JOB!', '2005-05-26 20:13:08.000000', NULL, 1),
(1414673, 180806, 32754, '<td valign="top">I like this...the rays of light hitting the subject are interesting, as are the shadows and holes in the wall. It has a soft, contemplative look...8</td>', 'I like this...the rays of light hitting the subject are interesting, as are the shadows and holes in the wall. It has a soft, contemplative look...8', '2005-05-26 20:14:00.000000', NULL, 1),
(1414676, 180289, 32754, '<td valign="top">Very dramatic use of light and shadow!  I like the person placed in the doorway and the jukebox on left. Original and interesting...</td>', 'Very dramatic use of light and shadow!  I like the person placed in the doorway and the jukebox on left. Original and interesting...', '2005-05-26 20:15:20.000000', NULL, 1),
