(1415551, 180537, 32948, '<td valign="top">beans look nice, better if the you went up a step or two with the fstop, better field of focus.  Light a bit too hot, and the uped fstop may have helped.  bracket.</td>', 'beans look nice, better if the you went up a step or two with the fstop, better field of focus.  Light a bit too hot, and the uped fstop may have helped.  bracket.', '2005-05-27 09:35:33.000000', NULL, 1),
