INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1417625, 180542, 29154, '<td valign="top">Great color and nice composition.</td>', 'Great color and nice composition.', '2005-05-28 14:18:14.000000', NULL, 1),
(1417627, 180601, 29154, '<td valign="top">Beautiful photo ! Perfect lighting !</td>', 'Beautiful photo ! Perfect lighting !', '2005-05-28 14:19:39.000000', NULL, 1),
(1417628, 180526, 29154, '<td valign="top">Great lighting but too much negative space IMO.</td>', 'Great lighting but too much negative space IMO.', '2005-05-28 14:20:24.000000', NULL, 1),
(1417631, 179749, 29154, '<td valign="top">Interesting composition, but seems a little over processed IMO</td>', 'Interesting composition, but seems a little over processed IMO', '2005-05-28 14:23:29.000000', NULL, 1),
(1417632, 180803, 29154, '<td valign="top">The bottle looks really great, but the cropping is much too tight. You could have use more negative space.</td>', 'The bottle looks really great, but the cropping is much too tight. You could have use more negative space.', '2005-05-28 14:25:10.000000', NULL, 1),
(1417633, 180398, 29154, '<td valign="top">The warm tones are extremely nice, but you lost LOTS of quality in resizing. That''s very sad ....</td>', 'The warm tones are extremely nice, but you lost LOTS of quality in resizing. That''s very sad ....', '2005-05-28 14:26:45.000000', NULL, 1),
(1417659, 180798, 9149, '<td valign="top">This reminds Latour paintings.</td>', 'This reminds Latour paintings.', '2005-05-28 15:16:57.000000', NULL, 1),
(1417669, 180287, 9149, '<td valign="top">I would prefer the face in focus. Nice shot.</td>', 'I would prefer the face in focus. Nice shot.', '2005-05-28 15:18:38.000000', NULL, 1),
(1417686, 180525, 15711, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2005-05-28 15:25:35.000000', NULL, 1),
(1417714, 180798, 32754, '<td valign="top">Good image: lots of mood and suspense. I like her eyes and the silhouettes of her hands on the light...good facial expression and fading of image into darkness very effective...8</td>', 'Good image: lots of mood and suspense. I like her eyes and the silhouettes of her hands on the light...good facial expression and fading of image into darkness very effective...8', '2005-05-28 15:48:23.000000', NULL, 1),
(1417718, 180998, 32754, '<td valign="top">Wow!  This is spectacular..the color of this jellyfish, the soft look of the light and tentacles is just wonderful; it appears lit from within, I love this shot!  10  Back for another look:  my top pick..eerie and wonderful image.</td>', 'Wow!  This is spectacular..the color of this jellyfish, the soft look of the light and tentacles is just wonderful; it appears lit from within, I love this shot!  10  Back for another look:  my top pick..eerie and wonderful image.', '2005-05-28 15:49:30.000000', NULL, 1),
(1417723, 180356, 32754, '<td valign="top">Excellent macro shot..colors are good use of subtle primaries..</td>', 'Excellent macro shot..colors are good use of subtle primaries..', '2005-05-28 15:50:43.000000', NULL, 1),
(1417725, 179951, 32754, '<td valign="top">I like the tonal quality of this image... and dof is good</td>', 'I like the tonal quality of this image... and dof is good', '2005-05-28 15:51:15.000000', NULL, 1),
(1417727, 180318, 32754, '<td valign="top">I like this but maybe a little too much darkness..</td>', 'I like this but maybe a little too much darkness..', '2005-05-28 15:51:46.000000', NULL, 1),
(1417729, 181036, 32754, '<td valign="top">Lovely picture.  good silhouetting of trees and moon is interesting behind cloud cover..stick in front is slightly distracting.</td>', 'Lovely picture.  good silhouetting of trees and moon is interesting behind cloud cover..stick in front is slightly distracting.', '2005-05-28 15:52:52.000000', NULL, 1),
(1417731, 180889, 32754, '<td valign="top">color and spotlighting make for a very interesting picture..lots of power and drama</td>', 'color and spotlighting make for a very interesting picture..lots of power and drama', '2005-05-28 15:53:45.000000', NULL, 1),
(1417732, 180542, 32754, '<td valign="top">I like the position of the sunflower and the backlighting.</td>', 'I like the position of the sunflower and the backlighting.', '2005-05-28 15:54:12.000000', NULL, 1),
(1417733, 180992, 32754, '<td valign="top">Awesome shot taken in moonlight...soft and lovely composition.</td>', 'Awesome shot taken in moonlight...soft and lovely composition.', '2005-05-28 15:54:50.000000', NULL, 1),
(1417735, 179849, 32754, '<td valign="top">There is something about this image that really appeals to me..I think it''s the tone and the diagonals.</td>', 'There is something about this image that really appeals to me..I think it''s the tone and the diagonals.', '2005-05-28 15:56:15.000000', NULL, 1),
(1417738, 180707, 32754, '<td valign="top">Nice still life, good texture on pears from sidelighting.</td>', 'Nice still life, good texture on pears from sidelighting.', '2005-05-28 15:56:55.000000', NULL, 1),
(1417740, 180999, 32754, '<td valign="top">Very interesting image of light..love the blue neon and clarity is superb.</td>', 'Very interesting image of light..love the blue neon and clarity is superb.', '2005-05-28 15:57:25.000000', NULL, 1),
(1417883, 180808, 25464, '<td valign="top">The composition is very interesting.  I especially like the corner of green showing at the top and the light in the window.  Not sure about the inclusion of the actual light on the wall, but interesting.</td>', 'The composition is very interesting.  I especially like the corner of green showing at the top and the light in the window.  Not sure about the inclusion of the actual light on the wall, but interesting.', '2005-05-28 18:26:34.000000', NULL, 1),
(1417885, 179921, 25464, '<td valign="top">My eye is drawn directly to the first bright spot on the wall, and the rest of the composition becomes an afterthought.  I think this would have been more powerful a shot with a smaller apeture.  The end of the hall would have been more crisp and maybe the highlights would have accented the shot rather than taking it over.</td>', 'My eye is drawn directly to the first bright spot on the wall, and the rest of the composition becomes an afterthought.  I think this would have been more powerful a shot with a smaller apeture.  The end of the hall would have been more crisp and maybe the highlights would have accented the shot rather than taking it over.', '2005-05-28 18:29:29.000000', NULL, 1),
(1417889, 180587, 25464, '<td valign="top">a bit too soft for my taste, but interesting use of light.</td>', 'a bit too soft for my taste, but interesting use of light.', '2005-05-28 18:30:20.000000', NULL, 1),
(1417890, 180714, 25464, '<td valign="top">We have seen this shot a hundred times, but still lovely.</td>', 'We have seen this shot a hundred times, but still lovely.', '2005-05-28 18:31:03.000000', NULL, 1),
(1417892, 180887, 25464, '<td valign="top">I really like the feeling of this shot, but it needs a subject.  I would have cropped out the bit of sky showing in the upper right.  Put a horse in this scene and you''ve got it.</td>', 'I really like the feeling of this shot, but it needs a subject.  I would have cropped out the bit of sky showing in the upper right.  Put a horse in this scene and you''ve got it.', '2005-05-28 18:32:39.000000', NULL, 1),
(1417896, 180181, 25464, '<td valign="top">Can''t find much to pick on.  Simple and effective.  The border is complementary.  The only thing I see to point out is a sticker or something similar on the base of the glass that looks like it should have been removed and a smudge of some sort on the upper part of the base as well.  It doesn''t really say anything to me, but I could see it making a decent stock image.  Good.</td>', 'Can''t find much to pick on.  Simple and effective.  The border is complementary.  The only thing I see to point out is a sticker or something similar on the base of the glass that looks like it should have been removed and a smudge of some sort on the upper part of the base as well.  It doesn''t really say anything to me, but I could see it making a decent stock image.  Good.', '2005-05-28 18:35:10.000000', NULL, 1),
(1417902, 180615, 25464, '<td valign="top">I like this idea, but the window seems slightly tilted and I would rather see more of the seats than just the highlights.  I think this idea could be improved by catching the light coming through the window illuminating the seats at an angle rather than this straight on approach.</td>', 'I like this idea, but the window seems slightly tilted and I would rather see more of the seats than just the highlights.  I think this idea could be improved by catching the light coming through the window illuminating the seats at an angle rather than this straight on approach.', '2005-05-28 18:37:08.000000', NULL, 1),
