(1419140, 180300, 38457, '<td valign="top">THE COMPOSITION LACKS SOMETHING TO BE DESIRED. THE GRASS IS BLOWN OUT TO MUCH IN FOREGROUND. INFRARED IS BEING USED SO MUCH NOW BY EVERYBODY WHO THINKS THEY UNDERSTAND IT. TRY RE-SHOOTING IT AND START WITH THE COMPOSITION, THEN CHANGE IT TO INFRARED LOOK/FEEL.</td>', 'THE COMPOSITION LACKS SOMETHING TO BE DESIRED. THE GRASS IS BLOWN OUT TO MUCH IN FOREGROUND. INFRARED IS BEING USED SO MUCH NOW BY EVERYBODY WHO THINKS THEY UNDERSTAND IT. TRY RE-SHOOTING IT AND START WITH THE COMPOSITION, THEN CHANGE IT TO INFRARED LOOK/FEEL.', '2005-05-29 17:03:54.000000', NULL, 1),
(1419146, 180798, 19936, '<td valign="top">Likely to be controversial but you can''t argue that "light" is a major part of this photo.  Very moody.  Good job.</td>', 'Likely to be controversial but you can''t argue that "light" is a major part of this photo.  Very moody.  Good job.', '2005-05-29 17:11:17.000000', NULL, 1),
