(1419487, 180076, 22734, '<td valign="top">Interesting and a gas to look at.</td>', 'Interesting and a gas to look at.', '2005-05-29 22:23:30.000000', NULL, 1),
(1419492, 180798, 22734, '<td valign="top">A very good effect with a penetrating delivery.</td>', 'A very good effect with a penetrating delivery.', '2005-05-29 22:26:06.000000', NULL, 1),
