(1419508, 180287, 14700, '<td valign="top">Well lit but the photo is far too small.</td>', 'Well lit but the photo is far too small.', '2005-05-29 22:39:40.000000', NULL, 1),
(1419510, 180764, 14700, '<td valign="top">A challenging subject with the contrast in tones.  You could not have done better.  It looks natural but I bet you even posed this hansomly proud pet.  Well done.</td>', 'A challenging subject with the contrast in tones.  You could not have done better.  It looks natural but I bet you even posed this hansomly proud pet.  Well done.', '2005-05-29 22:41:14.000000', NULL, 1),
