(1421032, 180999, 27605, '<td valign="top">Hey, you werent'' lying that it was doing well!  Congrats, an exceptional image.  (Getting pretty used to those 6''s, huh)?</td>', 'Hey, you werent'' lying that it was doing well!  Congrats, an exceptional image.  (Getting pretty used to those 6''s, huh)?', '2005-05-30 14:58:57.000000', NULL, 0),
(1421087, 179076, 9906, '<td valign="top">This is a wonderful example of soft focus and has actually done pretty good in the scoring at this site.  Soft focus is very under appreciated here.  I for one love the effect.  I am kinda saddened though that you decided to frame it in such a large border.  I would have much rather seen  the shot using more of the frame.  I believe that would have gotten you a higher score.  I may be wrong, but that''s MHO.<br/>TC</td>', 'This is a wonderful example of soft focus and has actually done pretty good in the scoring at this site.  Soft focus is very under appreciated here.  I for one love the effect.  I am kinda saddened though that you decided to frame it in such a large border.  I would have much rather seen  the shot using more of the frame.  I believe that would have gotten you a higher score.  I may be wrong, but that''s MHO.TC', '2005-05-30 15:18:58.000000', NULL, 0),
(1421094, 180620, 33672, '<td valign="top">I don''t get it??? where''s the text????</td>', 'I don''t get it??? where''s the text????', '2005-05-30 15:19:57.000000', NULL, 0),
